    <style>
        *{box-sizing:border-box}body{margin:0;background:#eef3f0;color:#10251c;font-family:Arial,sans-serif}.page{min-height:100vh;display:grid;place-items:center;padding:34px}.wrap{width:min(900px,100%)}.tools{display:flex;justify-content:flex-end;gap:10px;margin-bottom:16px}.tools a,.tools button{border:0;border-radius:9px;padding:11px 16px;background:#126b4c;color:#fff;font-weight:700;text-decoration:none;cursor:pointer}.tools a{background:#fff;color:#126b4c;border:1px solid #b9cec5}.card{width:856px;max-width:100%;aspect-ratio:1.586/1;border-radius:24px;overflow:hidden;background:linear-gradient(135deg,#0a3023,#146b4d 65%,#d9a928);color:#fff;box-shadow:0 25px 60px #0b2a1c35;position:relative;padding:34px}.card:after{content:"";position:absolute;width:340px;height:340px;border:55px solid #ffffff12;border-radius:50%;right:-140px;top:-155px}.brand{display:flex;align-items:center;gap:13px}.brand img{width:58px;height:58px;object-fit:contain;background:#fff;border-radius:13px;padding:5px}.brand b{font-size:22px;display:block}.brand span{font-size:11px;letter-spacing:.16em;opacity:.78}.content{display:grid;grid-template-columns:155px 1fr 145px;gap:26px;align-items:end;margin-top:45px;position:relative;z-index:1}.photo{width:155px;height:155px;border:5px solid #fff;border-radius:20px;object-fit:cover;background:#e7eee9}.avatar{display:grid;place-items:center;color:#126b4c;font-size:54px;font-weight:800}.details small{display:block;font-size:10px;letter-spacing:.14em;opacity:.7;margin-bottom:5px}.details h1{font-size:26px;margin:0 0 19px}.details b{display:block;font-size:18px;margin-bottom:15px}.details p{margin:0;font-size:14px}.qr{background:#fff;border-radius:15px;padding:8px;text-align:center;color:#173526;font-size:9px}.qr img{width:125px;height:125px;display:block}.status{position:absolute;right:32px;top:31px;background:#ffffff1f;border:1px solid #ffffff38;border-radius:20px;padding:7px 13px;font-size:11px;text-transform:uppercase;font-weight:800}.note{text-align:center;color:#60746b;font-size:12px;margin-top:14px}@media print{body{background:#fff}.page{padding:0;min-height:0}.tools,.note{display:none}.card{box-shadow:none;border-radius:0;width:85.6mm;height:54mm;padding:4mm}.brand img{width:10mm;height:10mm}.brand b{font-size:11px}.brand span{font-size:6px}.content{grid-template-columns:24mm 1fr 22mm;gap:4mm;margin-top:5mm}.photo{width:24mm;height:24mm;border-width:1mm;border-radius:3mm}.details h1{font-size:11px;margin-bottom:2mm}.details b{font-size:9px;margin-bottom:2mm}.details p{font-size:7px}.details small{font-size:5px}.qr{padding:1mm}.qr img{width:20mm;height:20mm}.status{right:4mm;top:4mm;font-size:6px;padding:1mm 2mm}}
    </style>
