<body><main class="page"><div class="wrap"><div class="tools"><a href="{{ $pdfUrl }}">Download PDF</a><button onclick="window.print()">Print / Save PDF</button></div><section class="card"><span class="status">{{ $member->status }}</span><div class="brand"><img src="{{ asset('images/lda-sports-complex-logo.png') }}" alt="LDA"><div><b>LDA Sports Complex</b><span>{{ isset($familyMember) ? 'FAMILY MEMBERSHIP CARD' : 'DIGITAL MEMBERSHIP CARD' }}</span></div></div><div class="content">@if($photo)<img class="photo" src="{{ $photo }}" alt="Member photograph">@else<div class="photo avatar">{{ strtoupper(substr($member->full_name,0,1)) }}</div>@endif<div class="details"><small>MEMBER NAME</small><h1>{{ $member->full_name }}</h1><small>MEMBERSHIP NUMBER</small><b>{{ $member->membership_no ?: $member->customer_no }}</b><small>SPORTS COMPLEX</small><p>{{ $member->sportsComplex->name }}</p></div><div class="qr"><img src="{{ $qrCode }}" alt="Secure verification QR">Scan to verify</div></div></section><p class="note">The QR code opens a signed membership verification page. This card always uses the latest approved photograph.</p></div></main></body>
